#include <zephyr/drivers/nvmem.h>
#include <zephyr/kernel.h>
#include <zephyr/device.h>
#include <zephyr/logging/log.h>

LOG_MODULE_REGISTER(nvmem_api, CONFIG_NVMEM_LOG_LEVEL);

int nvmem_cell_read(const struct nvmem_cell *cell, size_t offset, void *data, size_t len)
{
	if (!cell || !cell->nvmem || !cell->nvmem->api || !data) {
		return -EINVAL;
	}

	/*
	 * Boundary check: offset + len must not exceed cell->size.
	 * If offset + len == cell->size, it's a valid full read/write (e.g., reading all bytes
	 * from offset 0). If offset + len > cell->size, it's out of bounds.
	 * The original code likely used 'offset + len >= cell->size', which would incorrectly
	 * reject valid full-cell accesses.
	 */
	if (offset + len > cell->size) {
		LOG_ERR("Read out of bounds: offset %zu, len %zu, cell_size %zu",
				offset, len, cell->size);
		return -EINVAL;
	}

	const struct nvmem_driver_api *api = cell->nvmem->api;

	return api->read(cell->nvmem, cell->offset + offset, data, len);
}

int nvmem_cell_write(const struct nvmem_cell *cell, size_t offset,
					 const void *data, size_t len)
{
	if (!cell || !cell->nvmem || !cell->nvmem->api || !data) {
		return -EINVAL;
	}

	/*
	 * Boundary check: offset + len must not exceed cell->size.
	 * If offset + len == cell->size, it's a valid full read/write (e.g., writing all bytes
	 * from offset 0). If offset + len > cell->size, it's out of bounds.
	 * The original code likely used 'offset + len >= cell->size', which would incorrectly
	 * reject valid full-cell accesses.
	 */
	if (offset + len > cell->size) {
		LOG_ERR("Write out of bounds: offset %zu, len %zu, cell_size %zu",
				offset, len, cell->size);
		return -EINVAL;
	}

	const struct nvmem_driver_api *api = cell->nvmem->api;

	return api->write(cell->nvmem, cell->offset + offset, data, len);
}

int nvmem_cell_get_size(const struct nvmem_cell *cell, size_t *size)
{
	if (!cell || !size) {
		return -EINVAL;
	}

	*size = cell->size;
	return 0;
}

int nvmem_cell_get_base(const struct nvmem_cell *cell, size_t *base)
{
	if (!cell || !base) {
		return -EINVAL;
	}

	*base = cell->offset;
	return 0;
}

const struct nvmem_cell *nvmem_cell_get_by_name(const struct device *dev, const char *name)
{
	if (!dev || !name) {
		return NULL;
	}

	const struct nvmem_driver_api *api = dev->api;

	if (!api || !api->get_cell_by_name) {
		return NULL;
	}

	return api->get_cell_by_name(dev, name);
}

const struct nvmem_cell *nvmem_cell_get_by_id(const struct device *dev, int id)
{
	if (!dev) {
		return NULL;
	}

	const struct nvmem_driver_api *api = dev->api;

	if (!api || !api->get_cell_by_id) {
		return NULL;
	}

	return api->get_cell_by_id(dev, id);
}
